336	// Failure carries a stable machine-readable code and a human-readable reason.
337	type Failure struct {
338		Code       string   `json:"code"`
339		Reason     string   `json:"reason"`
340		Candidates []string `json:"candidates,omitempty"`
341	}
342	
343	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
344	
345	func failuref(code, format string, args ...any) *Failure {
346		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
347	}
