349	// ParseConfig parses and fully validates the route configuration.
350	func ParseConfig(data []byte) (*Config, *Failure) {
351		var cfg Config
352		if err := json.Unmarshal(data, &cfg); err != nil {
353			if f, ok := err.(*Failure); ok {
354				return nil, f
355			}
356			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
357		}
358		if f := cfg.validate(); f != nil {
359			return nil, f
360		}
361		return &cfg, nil
362	}
363	
364	func (cfg *Config) validate() *Failure {
365		seenIDs := make(map[string]int, len(cfg.Routes))
366		for i := range cfg.Routes {
367			route := &cfg.Routes[i]
368			loc := fmt.Sprintf("route %d", i+1)
369			if route.ID == "" {
370				return failuref("invalid_config", "%s: id must be non-empty", loc)
371			}
372			if first, ok := seenIDs[route.ID]; ok {
373				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
374			}
375			seenIDs[route.ID] = i + 1
376	
377			if len(route.Methods) == 0 {
378				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
379			}
380			for _, method := range route.Methods {
381				switch {
382				case method == "":
383					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
384				case method == "*":
385					// Wildcard matching any legal method.
386				case !isToken(method):
387					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
388				}
389			}
390	
391			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
392				return f
393			}
394			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
395				return f
396			}
397		}
398		return nil
399	}
400	
401	func validatePrefix(prefix, loc, id string) *Failure {
402		switch {
403		case prefix == "" || prefix[0] != '/':
404			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
405		case prefix != "/" && strings.HasSuffix(prefix, "/"):
406			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
407		case strings.ContainsAny(prefix, "?#"):
408			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
409		case !validPercentEscapes(prefix):
410			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
411		}
412		return nil
413	}
414	
415	func validateUpstream(raw, loc, id string) *Failure {
416		if strings.ContainsAny(raw, "?#") {
417			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
418		}
419		// Validate any bracketed host against the raw string before url.Parse:
420		// square brackets are the IP-literal marker, so whatever they enclose
421		// must be a legal IPv6 address (zone included) rather than a name or an
422		// IPv4 address. Doing this explicitly keeps the rule independent of
423		// url.Parse's parser strictness and lets the reason name the field and
424		// the actual problem instead of surfacing a generic URL parse error.
425		if f := validateBracketedUpstreamHost(raw, loc, id); f != nil {
426			return f
427		}
428		u, err := url.Parse(raw)
429		if err != nil {
430			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
431		}
432		if u.Scheme != "http" && u.Scheme != "https" {
433			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
434		}
435		if u.Host == "" {
436			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
437		}
438		return nil
439	}
440	
441	// validateBracketedUpstreamHost checks the raw upstream's authority for an
442	// IP literal in square brackets: brackets are reserved for an IPv6 (or
443	// future IP-version) literal, so their content must parse as an IPv6 address
444	// — full form, compressed form or an IPv6 address with an embedded IPv4
445	// tail — and the brackets must wrap the whole host exactly once:
446	//
447	//	"[" IPv6 "]" [ ":" *DIGIT ]
448	//
449	// A port, userinfo and a percent-encoded zone ("%25eth0") are allowed and
450	// never alter the literal's bytes; an empty pair of brackets, a plain
451	// hostname such as "[not-an-ip]", a bare IPv4 address such as
452	// "[127.0.0.1]", a malformed IPv6 literal, a missing closing bracket, a
453	// second bracket group such as "[::1][::2]", a stray closing bracket or any
454	// other text between the closing bracket and the start of the base path
455	// (including junk around the port such as "[::1]:80a" or "[::1]x]:80") are
456	// rejected — a legal first literal never legitimizes trailing content. The
457	// reason names the route, its id and the upstream field. This is a content
458	// error in a syntactically valid JSON document, never a JSON parse failure,
459	// and the rule is enforced here on the raw bytes rather than left to
460	// url.Parse's parser strictness.
461	func validateBracketedUpstreamHost(raw, loc, id string) *Failure {
462		// The authority starts after the scheme separator and ends at the first
463		// path slash (query and fragment were rejected by the caller).
464		schemeEnd := strings.Index(raw, "://")
465		if schemeEnd < 0 {
466			return nil // no scheme: the generic absolute-URL check reports this
467		}
468		authority := raw[schemeEnd+3:]
469		if i := strings.IndexByte(authority, '/'); i >= 0 {
470			authority = authority[:i]
471		}
472		// Any userinfo precedes the host and ends at the last '@'.
473		hostPort := authority
474		if i := strings.LastIndexByte(authority, '@'); i >= 0 {
475			hostPort = authority[i+1:]
476		}
477	
478		if !strings.ContainsAny(hostPort, "[]") {
479			return nil // ordinary reg-name (domain) or bare IPv4 host stays as-is
480		}
481		label := routeLabel(loc, id)
482		if !strings.HasPrefix(hostPort, "[") {
483			return failuref("invalid_config",
484				"%s: upstream bracketed host must be a single '[' IPv6 address ']' pair: '[' may only open the host", label)
485		}
486		closeBracket := strings.IndexByte(hostPort, ']')
487		if closeBracket < 0 {
488			return failuref("invalid_config",
489				"%s: upstream bracketed host must be a valid IPv6 address but the closing ']' is missing", label)
490		}
491		literal := hostPort[1:closeBracket]
492		// The zone delimiter is percent-encoded in the URL ("%25"); decode the
493		// literal's escapes once so netip sees "fe80::1%eth0" while every other
494		// byte keeps its original spelling.
495		decoded, err := url.PathUnescape(literal)
496		if err != nil {
497			return invalidBracketedHost(label, literal)
498		}
499		addr, err := netip.ParseAddr(decoded)
500		if err != nil || !addr.Is6() {
501			// ParseAddr accepts a bare IPv4 address; brackets may only carry
502			// IPv6, so "[127.0.0.1]" is rejected even though it is a valid IP.
503			return invalidBracketedHost(label, literal)
504		}
505		// The one closing bracket ends the host: the rest of the authority may
506		// be empty or the optional port the generic parser already allows
507		// (":" followed by digits, an empty port included). A repeated bracket
508		// group, a stray ']', or any other text before, beside or after a port
509		// fails here even though the first literal was valid — the brackets
510		// must enclose the whole host exactly once.
511		suffix := hostPort[closeBracket+1:]
512		switch {
513		case suffix == "":
514			return nil
515		case strings.ContainsAny(suffix, "[]"):
516			return invalidBracketedHostShape(label, suffix)
517		case suffix[0] != ':':
518			return invalidBracketedHostShape(label, suffix)
519		}
520		port := suffix[1:]
521		for i := 0; i < len(port); i++ {
522			if port[i] < '0' || port[i] > '9' {
523				return invalidBracketedHostShape(label, suffix)
524			}
525		}
526		return nil
527	}
528	
529	// invalidBracketedHost builds the content error for a bracketed host whose
530	// content is not a legal IPv6 literal.
531	func invalidBracketedHost(label, literal string) *Failure {
532		return failuref("invalid_config",
533			"%s: upstream host in brackets must be a valid IPv6 address, but %q is not a legal IPv6 address", label, literal)
534	}
535	
536	// invalidBracketedHostShape builds the content error for a bracketed host
537	// whose trailing bytes break the "single '[' IPv6 ']' pair plus optional
538	// port" grammar, e.g. a repeated bracket group, a stray closing bracket or
539	// non-port text after the closing bracket.
540	func invalidBracketedHostShape(label, suffix string) *Failure {
541		return failuref("invalid_config",
542			"%s: upstream bracketed host must be a single '[' IPv6 address ']' pair followed only by an optional port, but %q follows the closing ']'", label, suffix)
543	}
544	
545	// requestJSON mirrors Request but keeps method and target raw, so a valid
546	// JSON document whose fields merely have the wrong JSON type is reported on
547	// the offending field instead of as a generic JSON decode error.
548	type requestJSON struct {
549		Method json.RawMessage `json:"method"`
550		Target json.RawMessage `json:"target"`
551	}
552	
553	// ParseRequest parses and validates one JSON request. Three failure shapes are
554	// kept apart: a document whose JSON syntax is broken fails as a parse failure
555	// without guessing a field; a syntactically valid non-object document (array,
556	// number, string, boolean or null) must be a JSON object; a valid object whose
557	// method or target is not a string fails on that field, naming the JSON type
558	// actually received (null counts as a type error, never as a missing field).
559	// method is always checked before target, regardless of the key order in the
560	// object. Only after both fields are present strings are their contents
561	// (required method, legal token, absolute target without a fragment or a bad
562	// percent escape) validated, so an empty string stays a content error.
563	func ParseRequest(data []byte) (*Request, *Failure) {
564		var doc json.RawMessage
565		if err := json.Unmarshal(data, &doc); err != nil {
566			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
567		}
568		body := bytes.TrimSpace(doc)
569		if len(body) == 0 || body[0] != '{' {
570			return nil, failuref("invalid_request", "request must be a JSON object")
571		}
572	
573		var rj requestJSON
574		if err := json.Unmarshal(body, &rj); err != nil {
575			// The document already parsed as one JSON value and starts with '{';
576			// keep this as a parse failure rather than a field error if the object
577			// itself cannot be read.
578			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
579		}
580	
581		var req Request
582		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
583			return nil, f
584		}
585		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
586			return nil, f
587		}
588	
589		switch {
590		case req.Method == "":
591			return nil, failuref("invalid_request", "method is required")
592		case !isToken(req.Method):
593			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
594		}
595		switch {
596		case req.Target == "" || req.Target[0] != '/':
597			return nil, failuref("invalid_request", "target must start with /")
598		case strings.Contains(req.Target, "#"):
599			return nil, failuref("invalid_request", "target must not contain a fragment")
600		case !validPercentEscapes(req.Target):
601			return nil, failuref("invalid_request", "target contains an invalid percent escape")
602		}
603		return &req, nil
604	}
605	
606	// decodeRequestStringField type-checks one request field that must hold a
607	// string. An absent field (no such key) is left as the zero value so the
608	// later content checks keep their "field is required" behavior; null or any
609	// non-string JSON value is a type error that names the field and the JSON
610	// type that was actually supplied.
611	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
612		if len(raw) == 0 {
613			return nil
614		}
615		if jsonString(raw, dst) {
616			return nil
617		}
618		return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
619	}
620	
621	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
622	// terms the request error reasons use: "null", "a boolean", "a number",
623	// "a string", "an array" or "an object".
624	func jsonTypeName(raw json.RawMessage) string {
625		switch bytes.TrimSpace(raw)[0] {
626		case 'n':
627			return "null"
628		case 't', 'f':
629			return "a boolean"
630		case '"':
631			return "a string"
632		case '[':
633			return "an array"
634		case '{':
635			return "an object"
636		default:
637			return "a number"
638		}
639	}
640	
641	// Resolve matches a validated request against a validated configuration and
642	// computes the upstream URL. Failure codes are route_not_found and
643	// route_conflict.
644	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
645		path := req.Target
646		if i := strings.IndexByte(path, '?'); i >= 0 {
647			path = path[:i]
648		}
649	
650		type candidate struct {
651			route    *Route
652			concrete bool
653		}
654		var matched []candidate
655		for i := range cfg.Routes {
656			route := &cfg.Routes[i]
657			concrete, wildcard := methodMatch(route.Methods, req.Method)
658			if !concrete && !wildcard {
659				continue
660			}
661			if !prefixMatch(route.PathPrefix, path) {
662				continue
663			}
664			matched = append(matched, candidate{route, concrete})
665		}
666		if len(matched) == 0 {
667			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
668		}
669	
670		// Longest prefix wins.
671		bestLen := 0
672		for _, c := range matched {
673			if n := len(c.route.PathPrefix); n > bestLen {
674				bestLen = n
675			}
676		}
677		winners := matched[:0]
678		for _, c := range matched {
679			if len(c.route.PathPrefix) == bestLen {
680				winners = append(winners, c)
681			}
682		}
683	
684		// Among equal prefixes a concrete method beats the wildcard.
685		var concrete []candidate
686		for _, c := range winners {
687			if c.concrete {
688				concrete = append(concrete, c)
689			}
690		}
691		if len(concrete) > 0 {
692			winners = concrete
693		}
694		if len(winners) > 1 {
695			ids := make([]string, 0, len(winners))
696			for _, c := range winners {
697				ids = append(ids, c.route.ID)
698			}
699			sort.Strings(ids)
700			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
701			f.Candidates = ids
702			return nil, f
703		}
704	
705		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
706		if f != nil {
707			return nil, f
708		}
709		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
710	}
711	
712	// methodMatch reports whether the method list matches the request method
713	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
714	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
715		for _, m := range methods {
716			switch {
717			case m == "*":
718				wildcard = true
719			case m == method:
720				concrete = true
721			}
722		}
723		return concrete, wildcard
724	}
725	
726	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
727	// treated as a separator and the root prefix matches every origin-path.
728	func prefixMatch(prefix, path string) bool {
729		if prefix == "/" {
730			return true
731		}
732		if path == prefix {
733			return true
734		}
735		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
736	}
737	
738	// joinUpstream strips the route prefix from the request path and joins the
739	// remainder onto the upstream base path with exactly one slash at the
740	// junction. The junction is one run of literal slashes: every trailing
741	// slash on the base path and every leading slash on the remainder are
742	// merged into that single slash, even when either side contributes
743	// several. Nothing else is normalized: slashes inside either part, the
744	// remainder's trailing slashes (once non-slash content has appeared),
745	// ".", ".." and percent escapes such as "%2F" are carried over byte for
746	// byte, never decoded first. The base path is sliced out of the raw
747	// upstream so joining never re-encodes, reorders or drops anything
748	// outside the junction. The raw query is preserved verbatim unless the
749	// route defines queryTransforms, in which case they rewrite it after
750	// route selection.
751	func joinUpstream(route *Route, path, target string) (string, *Failure) {
752		if _, err := url.Parse(route.Upstream); err != nil {
753			// Config validation already rejected this.
754			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
755		}
756	
757		var remainder string
758		switch {
759		case route.PathPrefix == "/":
760			// Root keeps the whole following path; "/" itself has an empty remainder.
761			if path != "/" {
762				remainder = path
763			}
764		default:
765			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
766		}
767	
768		// Slice the validated upstream raw so nothing outside the junction is
769		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
770		schemeEnd := strings.Index(route.Upstream, "://")
771		tail := route.Upstream[schemeEnd+3:]
772		hostPart, basePath := tail, ""
773		if i := strings.IndexByte(tail, '/'); i >= 0 {
774			hostPart, basePath = tail[:i], tail[i:]
775		}
776	
777		// Collapse only the junction run: all trailing slashes of the base
778		// path meet all leading slashes of the remainder, and the junction
779		// keeps exactly one slash whether or not anything follows them. A
780		// remainder made entirely of slashes has no content past the run, so
781		// it likewise ends in that single slash.
782		baseTrimmed := strings.TrimRight(basePath, "/")
783		rest := strings.TrimLeft(remainder, "/")
784		joined := baseTrimmed + "/" + rest
785	
786		result := route.Upstream[:schemeEnd+3] + hostPart + joined
787		query, f := applyQueryTransforms(route.QueryTransforms, target)
788		if f != nil {
789			return "", f
790		}
791		return result + query, nil
792	}
793	
794	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
795	func isToken(s string) bool {
796		if s == "" {
797			return false
798		}
799		for i := 0; i < len(s); i++ {
800			if !isTokenChar(s[i]) {
801				return false
802			}
803		}
804		return true
805	}
806	
807	func isTokenChar(c byte) bool {
808		switch {
809		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
810			return true
811		}
812		switch c {
813		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
814			return true
815		}
816		return false
817	}
818	
819	// validPercentEscapes checks that every "%' is followed by two hex digits.
820	// Matching and joining stay on raw strings, but malformed escapes are rejected
821	// up front for both prefixes and request targets.
822	func validPercentEscapes(s string) bool {
823		for i := 0; i < len(s); i++ {
824			if s[i] != '%' {
825				continue
826			}
827			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
828				return false
829			}
830			i += 2
831		}
832		return true
833	}
834	
835	func isHex(c byte) bool {
836		switch {
837		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
838			return true
839		}
840		return false
841	}
842

