		if !strings.Contains(f.Reason, want) {
			t.Fatalf("reason %q missing %q", f.Reason, want)
		}
	}
	if strings.Contains(f.Reason, "unknown op") {
		t.Fatalf("later route's type error must win, got %q", f.Reason)
	}
}
EOF
